<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Contract extends Model { protected $fillable=['project_id','phase_id','company_id','reference','title','province','amount','start_date','end_date','initial_financing_rate','category','signature_date','duration_months','activities','termination_date','termination_reason']; protected $casts=['amount'=>'decimal:2','initial_financing_rate'=>'decimal:2','start_date'=>'date','end_date'=>'date','signature_date'=>'date','duration_months'=>'integer','termination_date'=>'date']; public function project(){return $this->belongsTo(Project::class);} public function sites(){return $this->hasMany(ContractSite::class);} public function payments(){return $this->hasMany(ContractPayment::class);} public function progress(){return $this->hasMany(ProgressEntry::class);} public function guarantees(){return $this->hasMany(PerformanceGuarantee::class);} public function amendments(){return $this->hasMany(ContractAmendment::class);} public function documents(){return $this->hasMany(ContractDocument::class);} public function company(){return $this->belongsTo(Company::class);} public function phase(){return $this->belongsTo(ProjectPhase::class);} }
